//! Deterministic geometry artifact; generated bytes stay outside source control.
use board_renderer_core::{aura::gpu_geometry, types::RenderConfig};
fn main() -> Result<(), Box<dyn std::error::Error>> {
    let arguments: Vec<_> = std::env::args().collect();
    let config: RenderConfig = serde_json::from_slice(&std::fs::read(
        arguments.get(1).ok_or("Expected config path")?,
    )?)?;
    let started = std::time::Instant::now();
    let bytes = gpu_geometry::generate(&config)?;
    std::fs::write(arguments.get(2).ok_or("Expected output path")?, &bytes)?;
    let mut metadata = gpu_geometry::metadata(&bytes)?;
    metadata["hostPrepareMs"] = serde_json::json!(started.elapsed().as_secs_f64() * 1000.0);
    println!("{metadata}");
    Ok(())
}
